def handle(app, svc):
    try:
        resp = svc.apply(app)
    except Exception:
        return {"action": "queue_review", "limit": 0}

    if not isinstance(resp, dict):
        return {"action": "queue_review", "limit": 0}

    # API v2: {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    result = resp.get("result")
    if isinstance(result, dict):
        outcome = result.get("outcome")
        limit = result.get("credit_limit", 0)
    else:
        # Fallback to API v1 shape: {"decision": ..., "limit": int}
        outcome = resp.get("decision")
        limit = resp.get("limit", 0)

    if outcome in ("approved", "approve"):
        try:
            limit = int(limit)
        except (TypeError, ValueError):
            limit = 0
        return {"action": "issue", "limit": limit}

    if outcome in ("declined", "decline"):
        return {"action": "decline", "limit": 0}

    # manual_review or unknown -> queue for review
    return {"action": "queue_review", "limit": 0}

